import Foundation
import SpriteKit
import UIKit

enum HunterSpriteAssets {

    static let idleFrames: [SKTexture] =
        makeFrames(
            base64: idleSheet,
            frameCount: 8
        )

    static let attack1Frames: [SKTexture] =
        makeFrames(
            base64: attack1Sheet,
            frameCount: 9
        )

    static let attack2Frames: [SKTexture] =
        makeFrames(
            base64: attack2Sheet,
            frameCount: 7
        )

    static let strongFrames: [SKTexture] =
        makeFrames(
            base64: strongSheet,
            frameCount: 14
        )

    private static func makeFrames(
        base64: String,
        frameCount: Int
    ) -> [SKTexture] {
        guard
            let data = Data(base64Encoded: base64),
            let image = UIImage(data: data)
        else {
            return []
        }

        let sheet = SKTexture(image: image)
        sheet.filteringMode = .nearest

        let width =
            1.0 / CGFloat(frameCount)

        return (0..<frameCount).map { index in
            let texture =
                SKTexture(
                    rect:
                        CGRect(
                            x:
                                CGFloat(index)
                                * width,
                            y: 0,
                            width: width,
                            height: 1
                        ),
                    in: sheet
                )

            texture.filteringMode =
                .nearest

            return texture
        }
    }

    private static let idleSheet = """

"""

    private static let attack1Sheet = """

"""

    private static let attack2Sheet = """

"""

    private static let strongSheet = """

"""
}
